PRAGMA foreign_keys = ON;
CREATE TABLE model_profiles (id TEXT NOT NULL, version INTEGER NOT NULL, config TEXT NOT NULL, secret TEXT NOT NULL, capabilities TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE accounts (id TEXT PRIMARY KEY, name TEXT NOT NULL, origin TEXT NOT NULL, username_hint TEXT NOT NULL, secret TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE tasks (id TEXT PRIMARY KEY, version INTEGER NOT NULL, definition TEXT NOT NULL, status TEXT NOT NULL, next_run_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX task_due ON tasks(status,next_run_at);
CREATE TABLE task_versions (task_id TEXT NOT NULL, version INTEGER NOT NULL, definition TEXT NOT NULL, PRIMARY KEY(task_id,version));
CREATE TABLE devices (id TEXT PRIMARY KEY, name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, last_seen TEXT, revoked INTEGER NOT NULL DEFAULT 0, protocol_version INTEGER NOT NULL);
CREATE TABLE pairings (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, poll_hash TEXT NOT NULL, token_secret TEXT NOT NULL, device_id TEXT NOT NULL, name TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE runs (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, task_snapshot TEXT NOT NULL, status TEXT NOT NULL, scheduled_for TEXT NOT NULL, deadline TEXT NOT NULL, device_id TEXT, lease_epoch INTEGER NOT NULL DEFAULT 0, lease_expires_at TEXT, cancel_requested INTEGER NOT NULL DEFAULT 0, write_pending INTEGER NOT NULL DEFAULT 0, account_key TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, result TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX run_queue ON runs(status,created_at);
CREATE TABLE account_locks (account_key TEXT PRIMARY KEY, run_id TEXT NOT NULL UNIQUE);
CREATE TABLE claims (device_id TEXT NOT NULL, request_id TEXT NOT NULL, run_id TEXT NOT NULL, PRIMARY KEY(device_id,request_id));
CREATE TABLE run_events (id TEXT NOT NULL, run_id TEXT NOT NULL, sequence INTEGER NOT NULL, kind TEXT NOT NULL, message TEXT NOT NULL, at TEXT NOT NULL, PRIMARY KEY(run_id,id));
CREATE INDEX event_order ON run_events(run_id,sequence);
CREATE TABLE actions (run_id TEXT NOT NULL, action_id TEXT NOT NULL, digest TEXT NOT NULL, effect TEXT NOT NULL, status TEXT NOT NULL, PRIMARY KEY(run_id,action_id));
CREATE TABLE challenges (id TEXT PRIMARY KEY, run_id TEXT NOT NULL, lease_epoch INTEGER NOT NULL, version INTEGER NOT NULL, step_id TEXT NOT NULL, kind TEXT NOT NULL, instruction TEXT NOT NULL, target TEXT, action_digest TEXT, status TEXT NOT NULL, secret TEXT, delivery_id TEXT, image_id TEXT, expires_at TEXT NOT NULL, UNIQUE(run_id,step_id,version));
CREATE TABLE artifacts (id TEXT PRIMARY KEY, run_id TEXT NOT NULL, object_key TEXT NOT NULL, content_type TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE model_usage (id TEXT PRIMARY KEY, run_id TEXT, model_id TEXT NOT NULL, model_version INTEGER NOT NULL, input_tokens INTEGER, output_tokens INTEGER, at TEXT NOT NULL);
CREATE TABLE idempotency (key TEXT PRIMARY KEY, digest TEXT NOT NULL, resource_id TEXT NOT NULL);
